using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServerDemo;

/// <summary>
/// Each public method decorated with [McpServerTool] becomes a discoverable tool.
/// The MCP SDK uses [Description] attributes to generate the schema LLMs see.
/// Constructor parameters are resolved via DI — no manual wiring needed.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    // DI injects a named HttpClient configured in Program.cs
    public WeatherTools(HttpClient httpClient)
    {
        _http = httpClient;
    }

    [McpServerTool("get_forecast")]
    [Description("Get a 7-day weather forecast for a location using latitude and longitude.")]
    public async Task<string> GetForecastAsync(
        [Description("Latitude (e.g. 39.7456)")] double latitude,
        [Description("Longitude (e.g. -97.0892)")] double longitude,
        CancellationToken cancellationToken = default)
    {
        // NWS API: resolve grid point, then fetch forecast
        var pointUrl = $"points/{latitude:F4},{longitude:F4}";
        var point = await _http.GetFromJsonAsync<PointResponse>(pointUrl, cancellationToken)
            ?? throw new InvalidOperationException("Failed to resolve grid point.");

        var forecast = await _http.GetFromJsonAsync<ForecastResponse>(
            point.Properties.ForecastUrl, cancellationToken)
            ?? throw new InvalidOperationException("Failed to fetch forecast.");

        return string.Join("\n---\n", forecast.Properties.Periods.Select(p =>
            $"{p.Name}: {p.Temperature}°{p.TemperatureUnit} — {p.ShortForecast}"));
    }

    [McpServerTool("get_alerts")]
    [Description("Get active weather alerts for a US state (two-letter code, e.g. CA).")]
    public async Task<string> GetAlertsAsync(
        [Description("Two-letter US state code (e.g. CA, NY, TX)")] string state,
        CancellationToken cancellationToken = default)
    {
        var alertData = await _http.GetFromJsonAsync<AlertResponse>(
            $"alerts/active?area={state}", cancellationToken)
            ?? throw new InvalidOperationException("Failed to fetch alerts.");

        if (alertData.Features.Count == 0)
            return $"No active alerts for {state}.";

        return string.Join("\n---\n", alertData.Features.Select(f =>
            $"[{f.Properties.Severity}] {f.Properties.Event}\n" +
            $"Area: {f.Properties.AreaDesc}\n" +
            $"{f.Properties.Headline}"));
    }
}

// --- JSON DTOs for the National Weather Service API ---

public record PointResponse(
    [property: JsonPropertyName("properties")] PointProperties Properties);

public record PointProperties(
    [property: JsonPropertyName("forecast")] string ForecastUrl);

public record ForecastResponse(
    [property: JsonPropertyName("properties")] ForecastProperties Properties);

public record ForecastProperties(
    [property: JsonPropertyName("periods")] List<ForecastPeriod> Periods);

public record ForecastPeriod(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("temperature")] int Temperature,
    [property: JsonPropertyName("temperatureUnit")] string TemperatureUnit,
    [property: JsonPropertyName("shortForecast")] string ShortForecast);

public record AlertResponse(
    [property: JsonPropertyName("features")] List<AlertFeature> Features);

public record AlertFeature(
    [property: JsonPropertyName("properties")] AlertProperties Properties);

public record AlertProperties(
    [property: JsonPropertyName("event")] string Event,
    [property: JsonPropertyName("severity")] string Severity,
    [property: JsonPropertyName("areaDesc")] string AreaDesc,
    [property: JsonPropertyName("headline")] string? Headline);

