using McpServerDemo;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    // Register a named HttpClient that the SDK injects into WeatherTools
    .AddHttpClient<WeatherTools>(client =>
    {
        client.BaseAddress = new Uri("https://api.weather.gov/");
        client.DefaultRequestHeaders.UserAgent.ParseAdd("McpServerDemo/1.0");
    });

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()           // reads/writes JSON-RPC over stdin/stdout
    .WithToolsFromAssembly();             // discovers all [McpServerTool] methods

await builder.Build().RunAsync();

